let session=null,data=null,chapter=null,lesson=null,stepIndex=0,selected=null,checked=false,runtimePromise=null,running=false,consoleText='',lastRun=null,environment='',outputTab='console',chat=[],saveTimer,exam=null,examTimer,examQueue=Promise.resolve(),saveQueue=Promise.resolve();
