function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,5000);}
async function api(route,body){const r=await fetch('/api/'+route,{method:body===undefined?'GET':'POST',credentials:'same-origin',headers:body===undefined?{}:{'Content-Type':'application/json','X-Agstat-Request':'classroom'},body:body===undefined?undefined:JSON.stringify(body)});const result=await r.json();if(!r.ok){if(r.status===403&&/approval|Verify your email/.test(result.error||'')&&session){session.access=false;data=null;render();}throw Object.assign(new Error(result.error||'The service could not respond.'),{status:r.status});}return result;}
function asset(url){if(!url)return '#';if(/^https?:/.test(url))return url;return '/learning-assets/'+url.replace(/^\//,'');}
function passed(id){return chapterProgress['r-agriculture_'+id]?.stepIds||[];}
function completed(c){const total=data.learning.chapters.find(x=>x.id===c.id)?.steps.length||0;return total>0&&passed(c.id).length===total;}
function stats(){const all=data?.learning.chapters.flatMap(c=>c.steps)||[];const n=Object.values(chapterProgress).reduce((a,p)=>a+(p.stepIds?.length||0),0);return {n,total:all.length,xp:n*10,chapters:data?.course.chapters.filter(completed).length||0};}
function markdown(raw){
 const code=[];let text=String(raw||'').replace(/(`{3,})[^\n]*\n([\s\S]*?)\n\1/g,(_,fence,s)=>`\n\n@@CODE${code.push(s)-1}@@\n\n`);
 text=escape(text).replace(/!\[([^\]]*)\]\(([^\s)]+)(?:[^)]*)\)(?:\{[^}]*\})?/g,(_,alt,url)=>{if(!/^(images|figures|screenshots|assets)\/[\w./%+-]+$/.test(url))return `<p>${alt} — see the complete chapter for this illustration.</p>`;return `<img src="${asset('books/r-agriculture/'+url)}" alt="${alt}" loading="lazy">`;});
 text=text.replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,'<a href="$2" target="_blank" rel="noopener noreferrer">$1 ↗</a>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\{#[^}]+\}/g,'');
 return text.split(/\n\s*\n/).map(p=>{if(/^@@CODE\d+@@$/.test(p.trim()))return `<pre>${escape(code[Number(p.match(/\d+/)[0])])}</pre>`;if(p.trim().startsWith('|'))return '<table>'+p.split('\n').filter(x=>!/^\|?[\s:|-]+$/.test(x)).map(row=>'<tr>'+row.split('|').filter((_,i,a)=>i>0&&i<a.length-1).map(x=>'<td>'+x.trim()+'</td>').join('')+'</tr>').join('')+'</table>';return '<p>'+p.replace(/\n/g,'<br>')+'</p>';}).join('');
}
function landing(){return `<section class="hero"><div><span class="pill purple">LEARN R. THINK LIKE A SCIENTIST.</span><h1>Learn R.<br><em>Explore agricultural data.</em></h1><p>Your interactive agricultural statistics classroom. Learn with STAT MAASH, experiment in real R, and build understanding one challenge at a time.</p><button class="btn primary open-auth">Enter your classroom →</button><p><small>For registered students approved by the department.</small></p></div><div class="hero-art">${mascot}<span class="float-tag">✦ Your AI learning companion</span><span class="float-tag">&gt; let's grow together_</span></div></section><div class="feature-grid">${[['⌘','A real R workspace','Write code, explore data, and watch your plots come to life.'],['✧','Guidance that stays with you','STAT MAASH helps you reason through code, errors, and agricultural results.'],['✓','Learn. Try. Understand.','Interactive lessons, self-assessment, and practical challenges at your pace.']].map(x=>`<article class="card"><span class="feature-icon">${x[0]}</span><h3>${x[1]}</h3><p>${x[2]}</p></article>`).join('')}</div>`;}
function waiting(){const u=session.user;return `<section class="card gate">${mascot}<span class="pill ${u.status==='suspended'?'amber':'purple'}">${u.status==='suspended'?'ACCESS SUSPENDED':'YOUR STUDENT ACCOUNT'}</span><h1>${!u.verified?'One small step: verify your email.':u.status==='suspended'?'Please contact the department.':'You’re registered. Approval is next.'}</h1><p>Hello ${escape(u.name)}. ${!u.verified?'Open the latest verification email, then return here and select Check email verification.':'Your department administrator must approve your account before you can open lessons, books, or the R classroom.'}</p><p><strong>${escape(u.email)}</strong></p><div class="status-steps"><span class="done">✓ Registered</span><span class="${u.verified?'done':''}">${u.verified?'✓':'2'} Email verified</span><span class="${u.status==='approved'?'done':''}">${u.status==='approved'?'✓ Admin approved':'3 Admin approval'}</span></div><button class="btn primary" id="refresh-access">${!u.verified?'Check email verification ↻':'Check approval status ↻'}</button>${!u.verified?'<button class="btn subtle" id="resend-verification">Send a fresh verification email</button>':''} <button class="btn subtle" id="signout">Sign out</button><p><small>Use the newest verification link. If it has expired, choose Send a fresh verification email above.</small></p></section>`;}
function chapterCleared(id){const r=data.ratings?.['r-agriculture_'+id];return r?.passed===true||(r?.total>0&&r.score===r.total);}
function activeChapter(){return data.course.chapters.find(c=>!chapterCleared(c.id))||data.course.chapters.at(-1);}
function studentStages(id,stage){return `<div class="student-stages">${['Learn','Practise','Assess'].map((name,i)=>`<span class="${stage===i?'active':''}"><b>${i+1}</b>${name}</span>`).join('')}<span><b>✓</b>Next chapter</span></div>`;}
function studentHome(){const c=activeChapter(),l=data.learning.chapters.find(x=>x.id===c.id),record=chapterProgress['r-agriculture_'+c.id]||{},groups=topicGroups(c.id),read=groups.every(g=>g.items.every(s=>record.stepIds?.includes(s.id))),practised=record.stepIds?.includes(c.id+'-lab'),allDone=data.course.chapters.every(x=>chapterCleared(x.id));const stage=read?(practised?2:1):0;return `<section class="student-course card"><span class="eyebrow">YOUR R COURSE · CHAPTER ${Number(c.id)} OF 14</span><h1>${escape(c.title)}</h1><p>${escape(c.objectives)}</p>${studentStages(c.id,stage)}<div class="student-next"><h2>${allDone?'All chapters cleared':stage===0?'Learn this chapter':stage===1?'Put the idea into practice':'Check your understanding'}</h2><p>${allDone?'You can now take the final examination.':stage===0?'Read the topic, explore its worked examples, then continue at your own pace.':stage===1?'Complete one guided task in R. STAT MAASH can help when you get stuck.':'Answer the chapter questions. Get every answer correct to unlock the next chapter. You can retry.'}</p><a class="btn primary" href="${allDone?'#exam':stage===0?'#read/'+c.id:stage===1?'#practise/'+c.id:'#assess/'+c.id}">${allDone?'Open final examination':stage===0?'Continue learning →':stage===1?'Start R practice →':'Start chapter assessment →'}</a></div><p class="muted">${data.course.chapters.filter(x=>chapterCleared(x.id)).length} / 14 chapters cleared · Next chapter unlocks after you pass.</p><details><summary>Review a completed chapter</summary>${data.course.chapters.filter(x=>chapterCleared(x.id)).map(x=>`<p><a href="#read/${x.id}">${x.id} · ${escape(x.title)}</a></p>`).join('')||'<p>Your completed chapters will appear here.</p>'}</details></section>`;}
function studentRead(id,n){const c=data.course.chapters.find(x=>x.id===id),groups=topicGroups(id),record=chapterProgress['r-agriculture_'+id]||{},first=groups.findIndex(g=>!g.items.every(s=>record.stepIds?.includes(s.id))),i=n===undefined?Math.max(0,first):Math.max(0,Math.min(Number(n)||0,groups.length-1)),g=groups[i],quiz=data.learning.chapters.find(x=>x.id===id).steps.slice(g.items.at(-1).index+1,groups[i+1]?.first).find(step=>step.kind==='check');return `<section class="student-reading"><a href="#home" class="eyebrow">← YOUR COURSE</a>${studentStages(id,0)}<span class="eyebrow">CHAPTER ${id} · TOPIC ${i+1} OF ${groups.length}</span><h1>${escape(g.title)}</h1><article class="study-paper">${g.items.map(step=>step.kind==='code'?`<section class="worked-example"><strong>Worked R example</strong><pre>${escape(step.code)}</pre><button class="btn small" data-copy-example="${step.index}" data-chapter="${id}">Copy code</button></section>`:`<div class="prose study-prose">${markdown(step.body)}</div>`).join('')}<div class="study-question"><strong>Pause and think</strong><p>What does this idea mean for agricultural data? Predict what changes if you alter one input in an example.</p></div>${quiz?`<section class="study-inline-check"><span class="pill amber">QUICK CHECK</span><h3>${escape(quiz.prompt)}</h3>${quiz.options.map((answer,j)=>`<button class="answer-choice" data-study-answer="${j}" data-study-check="${data.learning.chapters.find(x=>x.id===id).steps.indexOf(quiz)}" data-study-chapter="${id}"><b>${String.fromCharCode(65+j)}</b>${escape(answer)}</button>`).join('')}<div id="study-check-feedback" role="status"></div></section>`:''}<div class="study-actions">${i?`<a href="#read/${id}/${i-1}" class="btn subtle">← Back</a>`:''}<button id="finish-reading" class="btn primary" data-chapter="${id}" data-topic="${i}">${i===groups.length-1?'Continue to R practice →':'Next topic →'}</button></div></article><details><summary>Read the original formatted chapter</summary><iframe title="Original chapter" class="book-frame" src="${asset(c.bookUrl)}" loading="lazy"></iframe></details></section>`;}
function studentPractice(id,assessment=false){const l=data.learning.chapters.find(c=>c.id===id),index=l.steps.findIndex(s=>s.kind===(assessment?'assessment':'challenge')),record=chapterProgress['r-agriculture_'+id]||{};if(!assessment&&!drafts[id]&&!record.draft)drafts[id]=l.steps[index].code;return studentStages(id,assessment?2:1)+workshop(id,index);}
